theorem QuarticQuery.winsAt_unique {κ : Type}
    {f : QuarticQuery.PartialBool κ} {C : QuarticQuery.Circuit κ} {ℓ r : ℕ}
    {x : QuarticQuery.BitInput (QuarticQuery.BitLoc ℓ r C.size κ)}
    {i i' : QuarticQuery.Column ℓ} {s s' : QuarticQuery.Address r}
    (h : QuarticQuery.WinsAt f C ℓ r x i s)
    (h' : QuarticQuery.WinsAt f C ℓ r x i' s') : i = i' ∧ s = s'

theorem QuarticQuery.winner_no_incoming_zero {κ : Type}
    {f : QuarticQuery.PartialBool κ} {C : QuarticQuery.Circuit κ} {ℓ r : ℕ}
    {x : QuarticQuery.BitInput (QuarticQuery.BitLoc ℓ r C.size κ)}
    {i : QuarticQuery.Column ℓ} {s : QuarticQuery.Address r}
    (h : QuarticQuery.WinsAt f C ℓ r x i s)
    (c : QuarticQuery.Column ℓ) (a : QuarticQuery.Address r) (hne : i ≠ c) :
    QuarticQuery.readX x i (QuarticQuery.pointerEquiv ℓ
      (QuarticQuery.readPointerBit x c a ⟨i, hne⟩)) = true

theorem QuarticQuery.winner_finds_zero {κ : Type}
    {f : QuarticQuery.PartialBool κ} {C : QuarticQuery.Circuit κ} {ℓ r : ℕ}
    {x : QuarticQuery.BitInput (QuarticQuery.BitLoc ℓ r C.size κ)}
    {i : QuarticQuery.Column ℓ} {s : QuarticQuery.Address r}
    (h : QuarticQuery.WinsAt f C ℓ r x i s)
    (j : QuarticQuery.Column ℓ) (hne : j ≠ i) :
    QuarticQuery.readX x j (QuarticQuery.pointerEquiv ℓ
      (QuarticQuery.readPointerBit x i s ⟨j, hne⟩)) = false

theorem QuarticQuery.winsAt_iff_paperWinsAt {κ : Type}
    {f : QuarticQuery.PartialBool κ} {C : QuarticQuery.Circuit κ} {ℓ r : ℕ}
    {x : QuarticQuery.BitInput (QuarticQuery.BitLoc ℓ r C.size κ)}
    {i : QuarticQuery.Column ℓ} {s : QuarticQuery.Address r} :
    QuarticQuery.WinsAt f C ℓ r x i s ↔ QuarticQuery.PaperWinsAt f C ℓ r x i s

theorem QuarticQuery.winsAt_iff_localTests {κ : Type}
    {f : QuarticQuery.PartialBool κ} {C : QuarticQuery.Circuit κ} {ℓ r : ℕ}
    {x : QuarticQuery.BitInput (QuarticQuery.BitLoc ℓ r C.size κ)}
    {i : QuarticQuery.Column ℓ} {s : QuarticQuery.Address r}
    (hC : QuarticQuery.CircuitRealises C f) :
    QuarticQuery.WinsAt f C ℓ r x i s ↔
      ∀ e : QuarticQuery.TestIndex ℓ r C.size, QuarticQuery.localTest C ℓ r x i s e = true

theorem QuarticQuery.addressedF_eq_true_iff {κ : Type}
    {f : QuarticQuery.PartialBool κ} {C : QuarticQuery.Circuit κ} {ℓ r : ℕ}
    {x : QuarticQuery.BitInput (QuarticQuery.BitLoc ℓ r C.size κ)} :
    QuarticQuery.addressedF f C ℓ r x = true ↔
      ∃ (i : QuarticQuery.Column ℓ) (s : QuarticQuery.Address r),
        QuarticQuery.WinsAt f C ℓ r x i s

theorem QuarticQuery.exists_failing_localTest {κ : Type}
    {f : QuarticQuery.PartialBool κ} {C : QuarticQuery.Circuit κ} {ℓ r : ℕ}
    {x : QuarticQuery.BitInput (QuarticQuery.BitLoc ℓ r C.size κ)}
    {i : QuarticQuery.Column ℓ} (hC : QuarticQuery.CircuitRealises C f)
    (hn : ¬ ∃ s : QuarticQuery.Address r, QuarticQuery.WinsAt f C ℓ r x i s)
    (s : QuarticQuery.Address r) :
    ∃ e : QuarticQuery.TestIndex ℓ r C.size, QuarticQuery.localTest C ℓ r x i s e = false

theorem QuarticQuery.localTests_iff_eq_of_winsAt {κ : Type}
    {f : QuarticQuery.PartialBool κ} {C : QuarticQuery.Circuit κ} {ℓ r : ℕ}
    {x : QuarticQuery.BitInput (QuarticQuery.BitLoc ℓ r C.size κ)}
    {i : QuarticQuery.Column ℓ} {s : QuarticQuery.Address r}
    (hC : QuarticQuery.CircuitRealises C f)
    (hw : QuarticQuery.WinsAt f C ℓ r x i s) (s' : QuarticQuery.Address r) :
    (∀ e : QuarticQuery.TestIndex ℓ r C.size, QuarticQuery.localTest C ℓ r x i s' e = true) ↔ s' = s
